		void UpdatePrintButton()
		{
			PrintButton.Text = Res.GetString("33c9b3a1-36ea-4c81-940b-6e375335db3d", "Send");
			PrintButton.Enabled = HasValidContainersToPrint();

			foreach (ContainerToSelectFromForPrinting container in DocumentContainers.ContainersToSelectFrom)
			{
				container.JC_Calc_PrintDocumentForContainerInfo.ValueChanged += JC_Calc_PrintDocumentForContainerInfo_ValueChanged;
			}
		}

		void JC_Calc_PrintDocumentForContainerInfo_ValueChanged(object sender, EventArgs e)
		{
			var containerToSelectFromForPrinting = ((ContainerToSelectFromForPrinting)sender);

			containerToSelectFromForPrinting.JC_EPANStatusForBindingInfo.ClearAllNotifications();

			if (containerToSelectFromForPrinting.JC_Calc_PrintDocumentForContainer)
			{
				var errorMessage = ZString.Empty;
				var commonContainer = containerToSelectFromForPrinting.Container;

				if (commonContainer.Consol.DepartureCTOAddress == null)
				{
					errorMessage = Res.GetString("8ced143a-2d1d-4a6c-afd3-8e25c1e2d5ab", "Operational Port is required.");
				}
				else
				{
					var operationalPort = commonContainer.Consol.DepartureCTOAddress.RelatedPortCode;

					if (operationalPort.Code.Equals("NZLYT")
							&& (commonContainer.GrossWeightVerifiedByAddress.IsEmpty
									|| commonContainer.JC_GrossWeightVerificationStatus.Equals(Constants.ContainerGrossWeightVerificationStatuses.Codes.NotVerified)
									|| commonContainer.JC_GrossWeightVerificationDateTime.IsEmpty))
					{
						errorMessage = Res.GetString("52b6cfcd-ffec-4d9e-8538-a5800e82099c", "Export Pre-Advice submissions to the Port of {0}," + System.Environment.NewLine + "the Verified Method, Verified Date, and VGM Verified By are mandatory.", operationalPort.RL_PortName);
					}
					else if (commonContainer.JC_GrossWeightVerificationStatus.Equals(Constants.ContainerGrossWeightVerificationStatuses.Codes.NotVerified) || commonContainer.JC_GrossWeightVerificationDateTime.IsEmpty)
					{
						errorMessage = Res.GetString("150834bc-9c38-4da0-a214-add09e456206", "Export Pre-Advice submissions to the Port of {0}," + System.Environment.NewLine + "the Verified Method and Verified Date are mandatory.", operationalPort.RL_PortName);
					}
				}

				if (!errorMessage.IsEmpty)
				{
					containerToSelectFromForPrinting.JC_EPANStatusForBindingInfo.AddError(errorMessage);
				}
			}

			PrintButton.Enabled = HasValidContainersToPrint();
		}

		bool HasValidContainersToPrint()
		{
			var printableContainers = DocumentContainers.ContainersToSelectFrom
				.OfType<ContainerToSelectFromForPrinting>()
				.Where(c => c.JC_Calc_PrintDocumentForContainer)
				.ToList();

			return printableContainers.Any() && printableContainers.All(c => !c.HasErrors);
		}

		DocumentContainers DocumentContainers
		{
			get { return (DocumentContainers)BusinessEntity; }
